function validDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T00:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===s}
function validate(s){if(!s||s.version!==2||!Array.isArray(s.couples)||!s.couples.length||!Array.isArray(s.records))return false;const ids=new Set();for(const c of s.couples){if(!c||typeof c.id!=='string'||ids.has(c.id)||!['name','self','partner'].every(k=>typeof c[k]==='string')||!['theme','bio','avatar','selfAvatar','partnerAvatar','selfSubtitle','partnerSubtitle','selfDetails','partnerDetails','pairQuote','relationship','dialogue','dialogueTitle','relationshipNote'].every(k=>c[k]===undefined||typeof c[k]==='string'))return false;ids.add(c.id)}const rids=new Set();for(const r of s.records){if(!r||typeof r.id!=='string'||rids.has(r.id)||!ids.has(r.couple)||!Object.hasOwn(kinds,r.type)||typeof r.title!=='string'||typeof r.body!=='string'||!validDate(r.date)||!Array.isArray(r.images)||!r.images.every(i=>i&&typeof i.id==='string'&&typeof i.src==='string'&&['name','text','ocrStatus'].every(k=>i[k]===undefined||typeof i[k]==='string'))||!['body','tags','artist','rights','category','link','note','timelineLabel','status','cover','createdAt'].every(k=>r[k]===undefined||typeof r[k]==='string')||(r.order!==undefined&&(!Number.isFinite(r.order))))return false;rids.add(r.id)}return s.legacy===undefined||Array.isArray(s.legacy)}
