function current(){return state.couples.find(c=>c.id===state.active)||state.couples[0]}
function allRecords(type=page){return state.records.filter(r=>r.couple===current().id&&r.type===type)}
function ordered(list,order=sort){return [...list].sort((a,b)=>order==='custom'?(a.order??1e9)-(b.order??1e9)||a.date.localeCompare(b.date)||a.id.localeCompare(b.id):(order==='asc'?1:-1)*(a.date.localeCompare(b.date)||((a.order||0)-(b.order||0)))||a.id.localeCompare(b.id))}
function filtered(){return ordered(allRecords().filter(r=>(!year||r.date.startsWith(year))&&(!category||r.category===category)&&[r.title,r.body,r.tags,r.timelineLabel,r.artist,r.note,...r.images.map(i=>i.text||'')].join(' ').toLowerCase().includes(search.toLowerCase())))}
function recordCount(r){return wordCount(r.body)+r.images.reduce((n,i)=>n+wordCount(i.text),0)}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('dear-us-archive',1);req.onupgradeneeded=()=>req.result.createObjectStore('archive');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('请关闭旧页面后重试'))})}
async function readDB(){return new Promise((resolve,reject)=>{const req=db.transaction('archive').objectStore('archive').get('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function putDB(next){return new Promise((resolve,reject)=>{const tx=db.transaction('archive','readwrite');tx.objectStore('archive').put(next,'state');tx.oncomplete=resolve;tx.onabort=tx.onerror=()=>reject(tx.error||Error('保存失败'))})}
async function commit(fn){if(saveBusy){toast('正在保存，请稍后');return false}if(readOnly||!db){toast('当前无法持久保存，请允许浏览器存储后刷新；可先导出备份');return false}saveBusy=true;const next=structuredClone(state);try{fn(next);if(!validate(next))throw Error('数据未通过校验');await putDB(next);state=next;$('#storageStatus').textContent='● 已保存在此浏览器';return true}catch(err){toast('保存失败，原数据未改动。请检查存储空间或先导出备份。');return false}finally{saveBusy=false}}
