function artMarkup(r){const themes=['sea','letter','flower','night','rose','sand'],theme=themes.includes(r.cover)?r.cover:'blank';const names={sea:['Summer,','with you.','A SEA OF AFFECTION'],letter:['A letter','to you.','WORDS WE KEEP'],flower:['In full','bloom.','ONLY FOR YOU'],night:['The quiet','hours.','STAY A LITTLE LONGER'],rose:['Closer','to you.','THE SHAPE OF US'],sand:['Everything,','with you.','A PERSONAL COLLECTION'],blank:['Dear','us.','YOUR COLLECTION STARTS HERE']};const a=names[theme];return `<div class="art-cover ${theme}" aria-hidden="true"><span class="orb"></span><em>${a[0]}<br>${a[1]}</em><small>${a[2]}</small></div>`}
function messages(body){return String(body||'').split('\n').filter(s=>s.trim()).map(line=>{const m=line.match(/^([^:：]{1,30})[:：]\s*(.*)$/);return m?{speaker:m[1],text:m[2],me:['我','me','Me',current().self].includes(m[1])}:{speaker:'',text:line,me:false}})}
function chatMarkup(r,preview=false){const list=messages(r.body).slice(0,preview?3:Infinity);return `<div class="${preview?'chat-cover':'reader-chat'}">${list.length?list.map(m=>`<div class="bubble ${m.me?'me':''}">${!preview&&m.speaker?`<span class="chat-speaker">${escapeHTML(m.speaker)}</span>`:''}${escapeHTML(m.text)}</div>`).join(''):'<p class="hint">聊天截图见下方图片</p>'}</div>`}
function tags(r){return String(r.tags||'').split(/[,，]/).map(t=>t.trim()).filter(Boolean).map(t=>`<span class="tag">#${escapeHTML(t)}</span>`).join('')}
function coverMarkup(r){const i=r.images.find(i=>imageURL(i.src));return i?`<img loading="lazy" src="${escapeHTML(imageURL(i.src))}" alt="${escapeHTML(r.title)}">${r.images.length>1?`<span class="cover-stack">▧ ${r.images.length}</span>`:''}`:r.type==='chat'?chatMarkup(r,true):artMarkup(r)}
function actions(r){return `<div class="post-actions"><span>${r.type==='story'?recordCount(r).toLocaleString()+' 字':r.type==='art'?escapeHTML(r.artist||'未填写作者'):escapeHTML(r.status||r.category||'已收藏')}</span><span><button data-action="edit" data-id="${escapeHTML(r.id)}">编辑</button> &nbsp; <button data-action="delete" data-id="${escapeHTML(r.id)}">删除</button></span></div>`}
