function storyMarkup(r,index){return `<article class="story-row" data-record="${escapeHTML(r.id)}" draggable="true"><span class="chapter-no">${String(index+1).padStart(2,'0')}</span><div><div class="eyebrow">${escapeHTML(r.date)} / ${escapeHTML(r.timelineLabel||r.category||'OUR STORY')} ${r.demo?' / 示例':''}</div><h3><button data-action="read" data-id="${escapeHTML(r.id)}">${escapeHTML(r.title)}</button></h3><p>${escapeHTML(r.body||r.images.map(i=>i.text).join('\n')||'图片故事 · 点击阅读')}</p><div class="tag-line">${tags(r)}</div></div>${actions(r)}<div class="story-order-actions"><button data-action="reorder-up" data-id="${escapeHTML(r.id)}" aria-label="上移故事">↑ 上移</button><button data-action="reorder-down" data-id="${escapeHTML(r.id)}" aria-label="下移故事">↓ 下移</button></div></article>`}
function renderProfile(){const c=current();$('#profile').innerHTML=`<div class="profile-header"><div class="avatar">${imageURL(c.avatar)?`<img src="${escapeHTML(imageURL(c.avatar))}" alt="关系头像">`:`<div class="avatar-inner">${escapeHTML((c.self||'M').slice(0,1))}<i>&</i></div>`}</div><div><div class="profile-title"><select id="coupleSelect" aria-label="切换关系">${state.couples.map(x=>`<option value="${escapeHTML(x.id)}" ${c.id===x.id?'selected':''}>${escapeHTML(x.name)}</option>`).join('')}</select><button data-action="profile">编辑主页</button><button data-action="new-couple" aria-label="新建关系">＋</button></div><div class="profile-stats"><span><b>${allRecords('art').length}</b>份稿件</span><span><b>${allRecords('story').length}</b>个故事</span><span><b>${allRecords('story').reduce((s,r)=>s+recordCount(r),0).toLocaleString()}</b>字收藏</span></div><div class="profile-bio"><strong>${escapeHTML(c.self)} & ${escapeHTML(c.partner)}</strong>${escapeHTML(c.bio||'只属于我们的私人收藏。')}</div></div><button class="text-btn" data-action="home">双人档案 ↗</button></div><div class="space-row"><span class="space-note">OUR LITTLE SPACES</span>${Object.entries(kinds).map(([key,v])=>`<button class="space-chip ${page===key?'active':''}" data-action="tab" data-page="${key}"><span class="mini-avatar">${v.icon}</span><span>${v.label}</span></button>`).join('')}</div>`}
function renderCollections(){renderProfile();$('#tabs').className='tabs';$('#tabs').innerHTML='<button data-action="home">♡ 双人档案</button>'+Object.entries(kinds).map(([key,v])=>`<button class="${page===key?'active':''}" aria-current="${page===key?'page':'false'}" data-action="tab" data-page="${key}"><span class="tab-icon">${v.icon}</span>${v.label}</button>`).join('');const k=kinds[page],ys=[...new Set(allRecords().map(r=>r.date.slice(0,4)))].sort().reverse(),cats=[...new Set(allRecords().map(r=>r.category).filter(Boolean))];$('#workspace').innerHTML=`<div class="collection-head"><div><div class="eyebrow">${k.en}</div><h1>${k.label}</h1><p>${k.desc}</p></div><div class="head-actions"><div class="view-toggle" aria-label="布局方式"><button data-action="layout" data-mode="grid" class="${mode==='grid'?'active':''}" aria-pressed="${mode==='grid'}">▦ 网格</button><button data-action="layout" data-mode="list" class="${mode==='list'?'active':''}" aria-pressed="${mode==='list'}">☷ 列表</button></div><button class="solid" data-action="new">＋ ${page==='story'?'添加故事':page==='chat'?'整理对话':'添加收藏'}</button></div></div><div class="toolbar"><input type="search" id="search" aria-label="搜索当前分类" placeholder="搜索标题、文案、标签或识别文字…" value="${escapeHTML(search)}"><select id="yearFilter" aria-label="筛选年份"><option value="">全部年份</option>${ys.map(y=>`<option ${year===y?'selected':''}>${y}</option>`).join('')}</select><select id="categoryFilter" aria-label="筛选分类"><option value="">全部分类</option>${cats.map(c=>`<option ${category===c?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select><select id="sortSelect" aria-label="排列顺序"><option value="desc" ${sort==='desc'?'selected':''}>时间 · 从新到旧</option><option value="asc" ${sort==='asc'?'selected':''}>时间 · 从旧到新</option>${page==='story'?`<option value="custom" ${sort==='custom'?'selected':''}>自定义章节顺序</option>`:''}</select><span class="result-count" id="resultCount"></span></div>${page==='story'?`<div class="story-navigation"><label for="storyScrubber">快速翻阅 <input id="storyScrubber" type="range" min="0" max="0" value="0" step="1" aria-label="拖动定位故事"></label><span id="jumpInfo" aria-live="polite"></span><small>拖动进度条定位任意篇章，或拖拽故事卡片调整章节顺序；编辑可修改发生日期。</small></div>`:''}<div id="collection"></div><div class="pagination" id="pagination"></div>`;renderCollection()}
function renderCollection(){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/PAGE_SIZE));pageNo=Math.min(pageNo,pages-1);$('#resultCount').textContent=`${list.length} ${page==='story'?'个故事':'份收藏'}`;const section=$('#collection');section.className=mode==='list'?(page==='story'?'story-list':'list-mode'):page==='inspo'?'inspiration-grid':'gallery-grid';const items=list.slice(pageNo*PAGE_SIZE,(pageNo+1)*PAGE_SIZE);section.innerHTML=items.length?items.map((r,i)=>mode==='list'&&page==='story'?storyMarkup(r,pageNo*PAGE_SIZE+i):postMarkup(r,pageNo*PAGE_SIZE+i)).join(''):'<div class="empty" style="grid-column:1/-1"><h3>留一处空白，等你收藏。</h3><p>添加图片、文字，或换一个搜索条件。</p></div>';$('#pagination').innerHTML=`<button data-action="prev" ${pageNo===0?'disabled':''}>← 上一页</button><span>${pageNo+1} / ${pages}</span><button data-action="next" ${pageNo===pages-1?'disabled':''}>下一页 →</button>`;const scrub=$('#storyScrubber');if(scrub){scrub.max=Math.max(0,list.length-1);scrub.disabled=!list.length;jumpIndex=Math.min(jumpIndex,Math.max(0,list.length-1));scrub.value=jumpIndex;updateJump(list)} }
function updateJump(list=filtered()){const r=list[jumpIndex];if($('#jumpInfo'))$('#jumpInfo').textContent=r?`${jumpIndex+1} / ${list.length} · ${r.date} · ${r.title}`:'暂无故事';if($('#storyScrubber'))$('#storyScrubber').setAttribute('aria-valuetext',r?`${r.date} ${r.title}`:'暂无故事')}
function jumpTo(index){const list=filtered();jumpIndex=Math.max(0,Math.min(index,list.length-1));const next=Math.floor(jumpIndex/PAGE_SIZE);if(pageNo!==next){pageNo=next;renderCollection()}updateJump(list);$$('[data-record]').forEach(el=>el.classList.toggle('drag-over',el.dataset.record===list[jumpIndex]?.id))}
function field(name,label,value='',type='text',hint=''){return `<div class="field"><label for="field-${name}">${label}</label>${type==='textarea'?`<textarea id="field-${name}" name="${name}" ${name==='body'?'class="long"':''}>${escapeHTML(value)}</textarea>`:`<input id="field-${name}" name="${name}" type="${type}" value="${escapeHTML(value)}" ${['title','name','self','partner','date'].includes(name)?'required':''} ${type==='number'?'step="any"':''} ${['title','name','self','partner'].includes(name)?'maxlength="160"':''}>`}${hint?`<p class="hint">${hint}</p>`:''}</div>`}
function selectField(name,label,value,options){return `<div class="field"><label for="field-${name}">${label}</label><select id="field-${name}" name="${name}">${options.map(o=>`<option ${value===o?'selected':''}>${escapeHTML(o)}</option>`).join('')}</select></div>`}
function openEditor(id){const r=id?state.records.find(r=>r.id===id):null;if(id&&!r)return;editing={kind:'record',id,type:r?.type||page};draftImages=structuredClone(r?.images||[]);$('#editorTitle').textContent=(r?'编辑':'新增')+kinds[editing.type].label;$('#editorEyebrow').textContent=kinds[editing.type].en;const type=editing.type;let html=field('title',type==='story'?'故事大标题':'标题',r?.title||'')+'<div class="field-grid">'+field('date',type==='story'?'故事发生日期':'归档日期',r?.date||today(),'date')+field('category','分类',r?.category||({art:'双人插画',story:'正文',inspo:'约稿构思',chat:'日常对话'}[type]))+'</div>';if(type==='story')html+='<div class="field-grid">'+field('timelineLabel','时间线说明（可自由填写）',r?.timelineLabel||'','text','例如：相识后的第二个冬天 / 现代线 · 初识')+field('order','自定义章节序号',r?.order??allRecords(type).length+1,'number','选择「自定义章节顺序」后生效，同序号按日期排序。')+'</div>';html+=field('body',type==='art'?'配图文案':type==='chat'?'对话文字':type==='inspo'?'灵感笔记':'故事正文',r?.body||'','textarea',type==='chat'?'每行一条，使用「我：内容」「你：内容」或「名字：内容」。也可以只上传聊天截图。':'')+'<div class="counter" id="textCounter"></div>';if(type==='art')html+='<div class="field-grid">'+field('artist','作者 / 画师署名',r?.artist||'')+field('rights','授权 / 使用范围',r?.rights||'')+'</div>';if(type==='inspo')html+=selectField('status','建设进度',r?.status||'待建设',['待建设','构思中','已采用','已归档']);html+='<div class="field-grid">'+field('tags','标签（逗号分隔）',r?.tags||'')+field('link','来源链接（可选）',r?.link||'','url')+'</div>'+field('note',type==='chat'?'来源 / 对话背景 / 备注':'备注（可选）',r?.note||'','textarea');html+=`<div class="upload-zone"><label for="imagesInput">＋ 导入图片 · 支持多图，依选择顺序排列</label><input id="imagesInput" type="file" multiple accept="image/png,image/jpeg,image/webp"><div class="upload-options">${['story','chat'].includes(type)?'<label><input id="autoOCR" type="checkbox" checked>导入后自动识别文字与字数</label>':'<label><input id="autoOCR" type="checkbox">同时识别图片文字</label>'}<label>识别语言 <select id="ocrLanguage"><option value="chi_sim+eng">简体中文 + English</option><option value="chi_tra+eng">繁体中文 + English</option><option value="eng">English</option><option value="kor+eng">한국어 + English</option></select></label></div><p class="hint">每次最多 20 张，每张原图不超过 15 MB；保存时最长边缩至 2400px。OCR 在本机进行，首次需联网下载引擎与语言包。模糊图片、艺术字与聊天界面可能误识别，请校对。</p></div>${type==='chat'?'<div class="field"><label for="textInput">也可导入 TXT 对话（追加到正文）</label><input id="textInput" type="file" accept=".txt,text/plain"></div>':''}<div class="ocr-status" id="ocrStatus" aria-live="polite"></div><div class="attachment-list" id="attachmentList"></div>`;$('#editorFields').innerHTML=html;$('#formMessage').textContent='';$('#saveButton').disabled=false;renderAttachments();updateCounter();$('#editorDialog').showModal()}
function profileEditor(fresh=false){if($('#settingsDialog').open)$('#settingsDialog').close();editing={kind:'profile',fresh};draftImages=[];const c=fresh?{name:'',self:'',partner:'',bio:'',theme:'huaian'}:current();$('#editorTitle').textContent=fresh?'新建双人档案':'编辑双人档案';$('#editorEyebrow').textContent='THE TWO OF US';$('#editorFields').innerHTML=field('name','关系空间名称',c.name)+selectField('theme','专属页面美化',c.theme||'huaian',['huaian','parker'])+'<p class="hint">huaian：怀安笺 · 古典纸笺；parker：Peter’s roll · 纽约胶片。</p>'+field('bio','主页短简介',c.bio,'textarea')+field('pairQuote','双人寄语',c.pairQuote||'The art of being us.')+field('relationship','关系关键词（逗号分隔）',c.relationship||'')+'<h3 class="form-section-title">关于梦女 / Myself</h3>'+field('self','梦女名字',c.self)+field('selfSubtitle','名字下的小标题 / 英文名',c.selfSubtitle||'MYSELF')+field('selfDetails','基本信息（每行「项目：内容」）',c.selfDetails||'身份：待填写\n生日：待填写\n性格：待填写\n喜欢：待填写','textarea')+field('selfAvatar','头像图片链接',/^data:/.test(c.selfAvatar||c.avatar||'')?'':c.selfAvatar||c.avatar||'','url')+'<div class="field"><label for="selfAvatarInput">或上传梦女头像</label><input id="selfAvatarInput" type="file" accept="image/png,image/jpeg,image/webp"></div><label class="hint"><input id="clearSelfAvatar" type="checkbox">清除梦女头像</label><h3 class="form-section-title">关于梦角 / Beloved</h3>'+field('partner','梦角名字',c.partner)+field('partnerSubtitle','名字下的小标题 / 英文名',c.partnerSubtitle||'BELOVED')+field('partnerDetails','基本信息（每行「项目：内容」）',c.partnerDetails||'所属作品：待填写\n身份：待填写\n生日：待填写\n性格：待填写','textarea')+field('partnerAvatar','头像图片链接',/^data:/.test(c.partnerAvatar||'')?'':c.partnerAvatar||'','url')+'<div class="field"><label for="partnerAvatarInput">或上传梦角头像</label><input id="partnerAvatarInput" type="file" accept="image/png,image/jpeg,image/webp"></div><label class="hint"><input id="clearPartnerAvatar" type="checkbox">清除梦角头像</label><h3 class="form-section-title">我们的相处方式 / Between us</h3>'+field('dialogueTitle','相处模式的小标题',c.dialogueTitle||'我们平常是这样的。')+field('dialogue','展示对话（每行「名字：内容」）',c.dialogue||'','textarea','梦女可使用「我」或填写梦女名字；其余角色显示在另一侧。')+field('relationshipNote','关系补充 / 相处模式说明',c.relationshipNote||'','textarea');$('#formMessage').textContent='头像支持 PNG / JPG / WebP，每张不超过 15 MB。所有信息与示例对话均可自由修改。';$('#saveButton').disabled=false;$('#editorDialog').showModal()}
function renderAttachments(){const el=$('#attachmentList');if(!el)return;el.innerHTML=draftImages.map((i,index)=>`<div class="attachment"><img src="${escapeHTML(imageURL(i.src))}" alt="附件 ${index+1}"><div><div class="attachment-meta">${index+1}. ${escapeHTML(i.name||'图片')} · <span id="imageCount-${escapeHTML(i.id)}">${wordCount(i.text)}</span> 字 · ${escapeHTML(i.ocrStatus||'未识别')}</div><div class="attachment-actions"><button type="button" data-action="image-up" data-id="${escapeHTML(i.id)}" ${index===0?'disabled':''}>↑</button><button type="button" data-action="image-down" data-id="${escapeHTML(i.id)}" ${index===draftImages.length-1?'disabled':''}>↓</button><button type="button" data-action="ocr-one" data-id="${escapeHTML(i.id)}">${i.text?'重新识别':'识别文字'}</button><button type="button" data-action="image-remove" data-id="${escapeHTML(i.id)}">移除</button></div><textarea aria-label="第 ${index+1} 张图片的识别文字，可修正" data-image-text="${escapeHTML(i.id)}" placeholder="识别结果会显示在这里，也可手动输入或修正。">${escapeHTML(i.text||'')}</textarea></div></div>`).join('');updateCounter()}
function updateCounter(){if(!$('#textCounter'))return;const n=wordCount($('#field-body')?.value),m=draftImages.reduce((s,i)=>s+wordCount(i.text),0);$('#textCounter').textContent=`正文 ${n.toLocaleString()} 字 · 图片识别 ${m.toLocaleString()} 字 · 合计 ${(n+m).toLocaleString()} 字（不含空白，含标点；图片识别需校对，重复内容不自动去重）`}
function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('文件读取失败'));r.readAsDataURL(file)})}
async function prepareImage(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15*1024*1024)throw Error('仅支持 PNG、JPEG、WebP，每张最多 15 MB');const src=await readFile(file);return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{try{const scale=Math.min(1,2400/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);resolve({id:uid(),src:canvas.toDataURL('image/jpeg',.92),name:file.name,text:'',ocrStatus:'未识别'})}catch{reject(Error('图片处理失败'))}};img.onerror=()=>reject(Error('无法打开图片'));img.src=src})}
async function uploadImages(files){if(uploadBusy||ocrBusy){toast('请等待当前导入或识别完成');return}if(files.length>20){toast('每次最多导入 20 张图片');return}uploadBusy=true;$('#saveButton').disabled=true;const added=[];try{for(const [index,file] of [...files].entries()){$('#ocrStatus').textContent=`正在处理图片 ${index+1} / ${files.length}…`;const img=await prepareImage(file);draftImages.push(img);added.push(img)}renderAttachments();$('#ocrStatus').textContent=`已导入 ${added.length} 张图片。`}catch(err){renderAttachments();$('#ocrStatus').textContent=err.message;toast(err.message)}finally{uploadBusy=false;$('#saveButton').disabled=false}if(added.length&&$('#autoOCR')?.checked)await recognizeImages(added);}
async function loadOCR(){if(globalThis.Tesseract)return globalThis.Tesseract;if(!ocrPromise)ocrPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';script.crossOrigin='anonymous';let timer=setTimeout(()=>{script.remove();reject(Error('识别引擎加载超时，请检查网络后重试'))},25000);script.onload=()=>{clearTimeout(timer);globalThis.Tesseract?resolve(globalThis.Tesseract):reject(Error('识别引擎不可用'))};script.onerror=()=>{clearTimeout(timer);script.remove();reject(Error('识别引擎下载失败，请检查网络后重试'))};document.head.append(script)}).catch(e=>{ocrPromise=null;throw e});return ocrPromise}
let ocrToken=0,cancelOCR=null;
function setOCRMessage(text){const el=$('#ocrStatus');if(el){el.textContent=text;if(ocrBusy){const b=document.createElement('button');b.type='button';b.dataset.action='cancel-ocr';b.className='text-btn';b.textContent=' · 取消识别';el.append(b)}}}
async function recognizeImages(images){if(ocrBusy||uploadBusy){toast('正在处理，请稍后');return}if(!images.length)return;ocrBusy=true;$('#saveButton').disabled=true;const token=++ocrToken,language=$('#ocrLanguage')?.value||'chi_sim+eng';let worker=null,timer=null;const canceled=new Promise((_,reject)=>{cancelOCR=()=>{ocrToken++;reject(Error('已取消识别；图片仍可保存'))};timer=setTimeout(()=>{ocrToken++;reject(Error('识别超时；图片仍可保存，可稍后重试'))},180000)});const job=(async()=>{setOCRMessage('准备识别引擎与语言包…');const T=await loadOCR();if(token!==ocrToken)return;worker=await T.createWorker(language,1,{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@5.1.1',logger:m=>{if(token===ocrToken)setOCRMessage(`${m.status==='recognizing text'?'正在识别':'正在准备识别资源'} · ${Math.round((m.progress||0)*100)}%`)}});if(token!==ocrToken){await worker.terminate();return}ocrWorker=worker;for(const [index,img] of images.entries()){if(token!==ocrToken)return;setOCRMessage(`识别图片 ${index+1} / ${images.length}…`);const result=await worker.recognize(img.src);if(token!==ocrToken)return;if(img.text?.trim()&&!confirm('图片已有文字，使用新的识别结果覆盖？'))continue;img.text=result.data.text.trim();img.ocrStatus=`已识别 · 置信度 ${Math.round(result.data.confidence)}%`;renderAttachments()}if(token===ocrToken)setOCRMessage('识别完成。请检查识别文字，字数会随校对实时更新。')})();try{await Promise.race([job,canceled])}catch(err){if(token===ocrToken||token+1===ocrToken)setOCRMessage(err.message||'识别失败，图片已保留；可重试或手动输入文字。')}finally{clearTimeout(timer);if(token===ocrToken)ocrToken++;ocrBusy=false;cancelOCR=null;ocrWorker=null;if(worker)await worker.terminate().catch(()=>{});$('#saveButton').disabled=false;const el=$('#ocrStatus');el?.querySelector('button')?.remove();updateCounter()}}
function closeEditor(){if(uploadBusy||ocrBusy){toast('正在处理图片；可先点「取消识别」再关闭');return}$('#editorDialog').close();editing=null}
$('#editorDialog').addEventListener('cancel',e=>{if(uploadBusy||ocrBusy){e.preventDefault();toast('请先取消识别或等待处理完成')}});
$('#editForm').addEventListener('submit',async e=>{e.preventDefault();if(ocrBusy||uploadBusy||!editing)return;const data=Object.fromEntries(new FormData(e.target));$('#saveButton').disabled=true;try{if(editing.kind==='profile'){for(const [key,inputId,clearId] of [['selfAvatar','selfAvatarInput','clearSelfAvatar'],['partnerAvatar','partnerAvatarInput','clearPartnerAvatar']]){let avatar=editing.fresh?'':current()[key]||(key==='selfAvatar'?current().avatar||'':'');if($('#'+clearId).checked)avatar='';if(data[key])avatar=safeURL(data[key]);const file=$('#'+inputId).files[0];if(file)avatar=(await prepareImage(file)).src;data[key]=avatar}data.avatar=data.selfAvatar;const fresh=editing.fresh;const ok=await commit(s=>{if(fresh){const c={...data,id:uid()};s.couples.push(c);s.active=c.id}else Object.assign(s.couples.find(c=>c.id===s.active),data)});if(ok){$('#editorDialog').close();render();toast('主页已保存')}return}if(!validDate(data.date)){toast('请填写有效日期');return}if(data.order!==undefined){data.order=Number(data.order);if(!Number.isFinite(data.order)){toast('章节序号必须是数字');return}}const old=state.records.find(r=>r.id===editing.id);const r={...old,...data,id:old?.id||uid(),couple:current().id,type:editing.type,images:structuredClone(draftImages),order:data.order??old?.order??state.records.length+1,createdAt:old?.createdAt||today(),updatedAt:today(),demo:false};if(await commit(s=>{const i=s.records.findIndex(x=>x.id===r.id);if(i>=0)s.records[i]=r;else s.records.push(r)})){$('#editorDialog').close();render();toast('收藏已保存')}}catch(err){toast(err.message||'保存失败')}finally{$('#saveButton').disabled=false}});
function openReader(id){const r=state.records.find(x=>x.id===id);if(!r)return;readerId=id;const link=safeURL(r.link);$('#reader').innerHTML=`<div class="reader-tools"><span class="eyebrow">${kinds[r.type].en}</span><div class="read-size"><button data-action="reader-smaller" aria-label="减小字号">A−</button><button data-action="reader-larger" aria-label="增大字号">A＋</button><button data-action="close-reader" aria-label="关闭阅读">× 关闭</button></div></div><div class="reader-heading"><div class="eyebrow">${escapeHTML(r.timelineLabel||r.category||'PRIVATE COLLECTION')}</div><h1>${escapeHTML(r.title)}</h1><div class="reader-meta">${escapeHTML(r.date)} · ${recordCount(r).toLocaleString()} 字（含图片校对文本） ${r.artist?' · '+escapeHTML(r.artist):''}${r.demo?' · 示例内容':''}</div><div class="tag-line">${tags(r)}</div></div>${r.type==='chat'?chatMarkup(r):r.body?`<div class="reader-prose" id="readerProse">${escapeHTML(r.body)}</div>`:''}${r.images.length?`<div class="reader-gallery">${r.images.map((i,n)=>`<div>${imageURL(i.src)?`<img loading="lazy" src="${escapeHTML(imageURL(i.src))}" alt="${escapeHTML(i.name||r.title)}">`:''}<div class="image-caption">${n+1} / ${r.images.length} · ${wordCount(i.text)} 字 · ${escapeHTML(i.ocrStatus||'未识别')}</div>${i.text?`<details><summary class="hint">查看校对文字</summary><div class="reader-prose">${escapeHTML(i.text)}</div></details>`:''}</div>`).join('')}</div>`:r.type==='art'?`<div style="height:360px">${artMarkup(r)}</div>`:''}${r.note?`<div class="reader-notes">${escapeHTML(r.note)}</div>`:''}${r.rights?`<p class="hint">授权 / 使用范围：${escapeHTML(r.rights)}</p>`:''}${link?`<a class="reader-link" href="${escapeHTML(link)}" target="_blank" rel="noopener noreferrer">查看来源 ↗</a>`:''}<div class="form-footer"><button data-action="reader-prev">← 上一篇</button><button data-action="edit-reader" data-id="${escapeHTML(r.id)}">编辑</button><button data-action="reader-next">下一篇 →</button></div>`;if(!$('#readerDialog').open)$('#readerDialog').showModal();$('#readerDialog').scrollTop=0}
function downloadBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='dear-us-完整备份-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('备份已导出，请保留在安全的位置')}
function showSettings(){$('#legacyInfo').textContent=`旧版保留 ${state.legacy?.length||0} 条记录，包含在完整备份中。新版仅显示四类馆藏。`;$('#settingsDialog').showModal()}
async function reorderStory(source,target){if(source===target)return;const list=ordered(allRecords('story'));const from=list.findIndex(r=>r.id===source),to=list.findIndex(r=>r.id===target);if(from<0||to<0)return;const [item]=list.splice(from,1);list.splice(to,0,item);if(await commit(s=>{list.forEach((r,i)=>{s.records.find(x=>x.id===r.id).order=i+1})})){sort='custom';render();toast('章节顺序已保存；故事发生日期保持原值')}}
root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='world'){if(await commit(s=>s.active=id)){resetFilters();render()}}else if(a==='tab'){page=b.dataset.page;resetFilters();render()}else if(a==='home'){page='home';render()}else if(a==='new')openEditor();else if(a==='edit')openEditor(id);else if(a==='read')openReader(id);else if(a==='layout'){mode=b.dataset.mode;render()}else if(a==='profile')profileEditor();else if(a==='new-couple')profileEditor(true);else if(a==='settings')showSettings();else if(a==='close-settings')$('#settingsDialog').close();else if(a==='close-reader')$('#readerDialog').close();else if(a==='close-editor')closeEditor();else if(a==='export')downloadBackup();else if(a==='import')$('#backupInput').click();else if(a==='clear-demo'){if(confirm('只删除所有标记为示例的内容？你编辑保存过的内容会保留。')){if(await commit(s=>s.records=s.records.filter(r=>!r.demo))){$('#settingsDialog').close();render();toast('示例已清空')}}}else if(a==='delete-couple'){if(state.couples.length===1){toast('至少保留一个关系空间');return}if(confirm(`永久删除「${current().name}」及其全部收藏？建议先导出备份。`)){if(await commit(s=>{s.records=s.records.filter(r=>r.couple!==s.active);s.couples=s.couples.filter(c=>c.id!==s.active);s.active=s.couples[0].id})){$('#settingsDialog').close();render()}}}else if(a==='delete'){if(confirm('删除这份收藏？此操作无法撤销。')){if(await commit(s=>s.records=s.records.filter(r=>r.id!==id)))render()}}else if(a==='prev'||a==='next'){pageNo+=a==='next'?1:-1;jumpIndex=pageNo*PAGE_SIZE;renderCollection();$('#collection').scrollIntoView({block:'start',behavior:'smooth'})}else if(a==='cancel-ocr'){cancelOCR?.()}else if(['image-remove','image-up','image-down','ocr-one'].includes(a)){if(ocrBusy||uploadBusy){toast('请先等待或取消当前识别');return}const i=draftImages.findIndex(x=>x.id===id);if(i<0)return;if(a==='ocr-one'){if(draftImages[i].text&&!confirm('重新识别可能覆盖已校对文本，继续？'))return;await recognizeImages([draftImages[i]])}else{if(a==='image-remove')draftImages.splice(i,1);else{const target=i+(a==='image-up'?-1:1);if(target>=0&&target<draftImages.length)[draftImages[i],draftImages[target]]=[draftImages[target],draftImages[i]]}renderAttachments()}}else if(a==='edit-reader'){$('#readerDialog').close();openEditor(id)}else if(a==='reader-prev'||a==='reader-next'){const r=state.records.find(x=>x.id===readerId),list=page===r.type?filtered():ordered(allRecords(r.type),'asc'),index=list.findIndex(x=>x.id===readerId),next=index+(a==='reader-next'?1:-1);if(next<0||next>=list.length)toast('已经是这一侧的最后一篇');else openReader(list[next].id)}else if(a==='reader-smaller'||a==='reader-larger'){$$('#reader .reader-prose').forEach(el=>{const n=parseFloat(getComputedStyle(el).fontSize);el.style.fontSize=Math.max(13,Math.min(24,n+(a==='reader-larger'?1:-1)))+'px'})}else if(a==='reorder-up'||a==='reorder-down'){const list=ordered(allRecords('story')),i=list.findIndex(r=>r.id===id),j=i+(a==='reorder-up'?-1:1);if(j>=0&&j<list.length)await reorderStory(id,list[j].id)}});
root.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){search=el.value;pageNo=0;jumpIndex=0;renderCollection()}else if(el.id==='storyScrubber')jumpTo(Number(el.value));else if(el.id==='field-body')updateCounter();else if(el.dataset.imageText){const i=draftImages.find(i=>i.id===el.dataset.imageText);if(i){i.text=el.value;i.ocrStatus='已校对';const count=$('#imageCount-'+i.id);if(count)count.textContent=wordCount(i.text);updateCounter()}}});
root.addEventListener('change',async e=>{const el=e.target;if(el.id==='coupleSelect'){if(await commit(s=>s.active=el.value)){resetFilters();render()}else render()}else if(['yearFilter','categoryFilter','sortSelect'].includes(el.id)){if(el.id==='yearFilter')year=el.value;if(el.id==='categoryFilter')category=el.value;if(el.id==='sortSelect')sort=el.value;pageNo=0;jumpIndex=0;renderCollection()}else if(el.id==='imagesInput'){await uploadImages([...el.files]);el.value=''}else if(el.id==='textInput'){const file=el.files[0];if(file){if(file.size>5*1024*1024){toast('TXT 文件最多 5 MB');return}$('#field-body').value+=($('#field-body').value?'\n':'')+await file.text();updateCounter();el.value=''}}});
root.addEventListener('dragstart',e=>{if(page!=='story')return;const card=e.target.closest('[data-record]');if(card){dragId=card.dataset.record;e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move'}});root.addEventListener('dragover',e=>{if(page==='story'&&dragId&&e.target.closest('[data-record]')){e.preventDefault();e.target.closest('[data-record]').classList.add('drag-over')}});root.addEventListener('dragleave',e=>e.target.closest('[data-record]')?.classList.remove('drag-over'));root.addEventListener('drop',async e=>{if(page!=='story'||!dragId)return;e.preventDefault();const t=e.target.closest('[data-record]');if(t)await reorderStory(dragId,t.dataset.record);dragId=null});root.addEventListener('dragend',()=>{dragId=null;$$('.drag-over').forEach(el=>el.classList.remove('drag-over'))});
$('#backupInput').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>250*1024*1024)throw Error('备份超过 250 MB，请使用较小的备份');const data=migrate(JSON.parse(await f.text()));if(!confirm('导入将替换全部现有关系与收藏。已导出当前备份并确定继续？'))return;if(!data.couples.some(c=>c.id===data.active))data.active=data.couples[0].id;if(await commit(next=>{for(const k of Object.keys(next))delete next[k];Object.assign(next,data)})){resetFilters();render();$('#settingsDialog').close();toast('馆藏已恢复')}}catch(err){toast(err.message||'备份无效，未更改当前馆藏')}finally{e.target.value=''}});
async function init(){try{db=await openDB();const existing=await readDB();if(existing){state=migrate(existing)}else{const old=localStorage.getItem('affection-archive-v1');if(old){state=migrate(JSON.parse(old));toast('已保留旧版稿件与信件，其余旧内容随备份保留')}await putDB(state)}if(!state.couples.some(c=>c.id===state.active))state.active=state.couples[0].id;$('#storageStatus').textContent='● 已保存在此浏览器'}catch(err){readOnly=true;$('#storageStatus').textContent='⚠ 存储不可用';toast('无法打开持久存储：请允许浏览器存储后刷新。本次仅供查看，无法保存。')}render()}
init();
function personPanel(c,side){const isSelf=side==='self',name=c[side]||'待填写',avatar=imageURL(c[side+'Avatar']||(isSelf?c.avatar:'')),subtitle=c[side+'Subtitle']||(isSelf?'MYSELF':'BELOVED'),details=c[side+'Details']||(isSelf?'身份：待填写\n生日：待填写\n性格：待填写':'所属作品：待填写\n身份：待填写\n性格：待填写');return `<article class="person-panel"><div class="portrait-frame">${avatar?`<img src="${escapeHTML(avatar)}" alt="${escapeHTML(name)}的头像">`:`<div class="portrait-placeholder ${isSelf?'warm':'cool'}"><span>${isSelf?'M.':'Y.'}</span><small>${isSelf?'MYSELF':'BELOVED'}</small></div>`}</div><div class="person-subtitle">${escapeHTML(subtitle)}</div><h2>${escapeHTML(name)}</h2><dl>${details.split('\n').filter(Boolean).map(line=>{const i=line.search(/[:：]/);return i>=0?`<div><dt>${escapeHTML(line.slice(0,i))}</dt><dd>${escapeHTML(line.slice(i+1))}</dd></div>`:`<div><dd>${escapeHTML(line)}</dd></div>`}).join('')}</dl></article>`}
function renderBaseHome(){const c=current();$('#profile').innerHTML=`<div class="dossier-heading"><div><div class="eyebrow">A PRIVATE PORTRAIT OF TWO</div><select id="coupleSelect" aria-label="切换双人档案">${state.couples.map(x=>`<option value="${escapeHTML(x.id)}" ${x.id===c.id?'selected':''}>${escapeHTML(x.name)}</option>`).join('')}</select></div><div><button data-action="profile">编辑双人档案 ↗</button><button class="text-btn" data-action="new-couple">＋ 新建关系</button></div></div><div class="duo-dossier">${personPanel(c,'self')}<div class="duo-center"><span class="duo-line"></span><span class="duo-and">&</span><span class="eyebrow">THE TWO OF US</span><p>${escapeHTML(c.pairQuote||'The art of being us.')}</p><span class="duo-line"></span></div>${personPanel(c,'partner')}</div><div class="pair-caption"><span>${escapeHTML(c.bio||'一些偏爱，一些关于我们的收藏。')}</span><div>${String(c.relationship||'').split(/[,，]/).filter(Boolean).map(x=>`<span class="relationship-tag">${escapeHTML(x)}</span>`).join('')}</div></div><section class="between-section"><div class="between-label"><span class="eyebrow">A LITTLE CONVERSATION</span><h2>${escapeHTML(c.dialogueTitle||'我们之间。')}</h2><p>${escapeHTML(c.relationshipNote||'一句熟悉的话，也可以是我们相处的缩影。')}</p></div><div class="duo-conversation">${messages(c.dialogue||'').map(m=>`<div class="duo-message ${m.me?'from-self':'from-partner'}"><span class="speaker-dot">${escapeHTML((m.me?c.self:c.partner).slice(0,1))}</span><div><span class="duo-speaker">${escapeHTML(m.speaker||(m.me?c.self:c.partner))}</span><p>${escapeHTML(m.text)}</p></div></div>`).join('')||'<p class="hint">编辑档案，写下代表你们相处模式的对话。</p>'}</div></section>`;$('#tabs').className='tabs';$('#tabs').innerHTML='<button class="active" data-action="home" aria-current="page">♡ 双人档案</button>'+Object.entries(kinds).map(([key,v])=>`<button data-action="tab" data-page="${key}"><span class="tab-icon">${v.icon}</span>${v.label}</button>`).join('');const recent=ordered(allRecords('art'),'desc').slice(0,3),stories=ordered(allRecords('story'),'desc').slice(0,2);$('#workspace').innerHTML=`<div class="collection-head"><div><div class="eyebrow">RECENTLY COLLECTED</div><h1>最近的珍藏</h1></div><button class="text-btn" data-action="tab" data-page="art">全部稿件 ↗</button></div><div class="gallery-grid">${recent.map(postMarkup).join('')||'<div class="empty" style="grid-column:1/-1"><h3>你们的收藏，从这里开始。</h3><button data-action="tab" data-page="art">添加第一份稿件 ↗</button></div>'}</div><div class="collection-head home-story-heading"><div><div class="eyebrow">PAGES OF US</div><h1>翻开我们的故事</h1></div><button class="text-btn" data-action="tab" data-page="story">完整目录 ↗</button></div><div class="home-story-grid">${stories.map((r,i)=>`<button class="home-story" data-action="read" data-id="${escapeHTML(r.id)}"><span class="eyebrow">${escapeHTML(r.date)} / ${escapeHTML(r.timelineLabel||'OUR STORY')}</span><h3>${escapeHTML(r.title)}</h3><p>${escapeHTML((r.body||'').slice(0,75)||'一段尚未翻开的故事。')}</p><span class="text-btn">继续阅读 ↗</span></button>`).join('')||'<p class="hint">在「我们的故事」添加第一个章节。</p>'}</div>`}
function render(){applyTheme();if(page==='home')renderHome();else renderCollections();themeNavigation()}
function themeId(){return current().theme==='parker'?'parker':'huaian'}
function applyTheme(){const theme=themeId();root.dataset.theme=theme;$('#worldSwitch').innerHTML=state.couples.map(c=>`<button class="world-option ${c.id===current().id?'selected':''}" data-action="world" data-id="${escapeHTML(c.id)}" aria-pressed="${c.id===current().id}"><span class="world-option-kicker">${c.theme==='parker'?'NEW YORK / 35MM':'古风 · 私藏笺册'}</span><span>${escapeHTML(c.partner)}</span><small>${c.theme==='parker'?'THE PARKER ROLL':'怀安笺'}</small></button>`).join('');$('.wordmark').innerHTML=theme==='parker'?'<span class="parker-logo">dear <i>us.</i></span><small>THE PARKER ROLL</small>':'<span class="huaian-logo">怀安笺</span><small>一笺心事 · 与君同记</small>'}
function themeNavigation(){if(themeId()!=='huaian')return;const labels={art:'丹青集 · 稿件',story:'故事卷 · 我们的故事',inspo:'拾意录 · 灵感',chat:'絮语匣 · 聊天'};$$('#tabs [data-page]').forEach(b=>{b.innerHTML=escapeHTML(labels[b.dataset.page])})}
function renderHome(){renderBaseHome();const c=current(),isParker=themeId()==='parker';const heading=$('.dossier-heading');heading.insertAdjacentHTML('afterend',`<section class="world-hero ${isParker?'city-hero':'ink-hero'}"><div class="world-hero-text"><span class="eyebrow">${isParker?'A LOVE STORY, SHOT ON 35MM':'逐玉 · 李怀安 · 私人梦向档案'}</span><h1>${isParker?'The city.<br>The boy.<br>The two of us.':'纸短情长<br><span>怀安入笺</span>'}</h1><p>${isParker?'Every ordinary moment, worth keeping.':'把相逢、同行与未尽之言，慢慢记下。'}</p><div class="hero-coordinate">${isParker?'NEW YORK CITY / PETER PARKER / ANDREW GARFIELD':'卷首 · 双人小传 / 相知絮语'}</div></div>${imageURL(c.partnerAvatar)?`<img class="hero-portrait" src="${escapeHTML(imageURL(c.partnerAvatar))}" alt="${escapeHTML(c.partner)}角色参考剧照">`:'<div class="hero-portrait hero-portrait-empty"></div>'}<div class="world-hero-mark" aria-hidden="true">${isParker?'P. / 01':'怀<br>安'}</div><span class="world-hero-rule" aria-hidden="true"></span></section>`);if(isParker){$('.duo-center').innerHTML='<span class="duo-line"></span><span class="duo-and">&</span><span class="eyebrow">A DOUBLE EXPOSURE</span><p>Somewhere in New York.</p><span class="duo-line"></span>'}else{const subtitle=$('.home-story-heading h1');if(subtitle)subtitle.textContent='翻一卷，关于你我';const recent=$('#workspace h1');if(recent)recent.textContent='新入丹青'} }
const originalArtMarkup=artMarkup;
artMarkup=function(r){if(themeId()==='huaian'){return `<div class="scroll-cover tone-${escapeHTML(['flower','sea','night','rose'].includes(r.cover)?r.cover:'paper')}"><span class="scroll-top">私藏丹青 · 李怀安</span><div class="scroll-landscape" aria-hidden="true"></div><strong>${escapeHTML(r.title.slice(0,8))}</strong><span class="scroll-annotation">${escapeHTML(r.date.replaceAll('-',' · '))}<br>一笺心事 · 与君同记</span><span class="scroll-seal" aria-hidden="true">藏</span><small>示例封面 / 可上传稿件替换</small></div>`}return `<div class="film-cover film-${escapeHTML(['night','sea','rose'].includes(r.cover)?r.cover:'paper')}"><span class="film-meta">PARKER / PRIVATE COLLECTION</span><div class="film-horizon" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><em>${escapeHTML(r.title)}</em><span class="film-date">${escapeHTML(r.date)}<br>AN ORDINARY MOMENT, WITH YOU.</span><small>示例封面 · YOUR ART GOES HERE</small></div>`};
